CREATE FUNCTION public.finance_schedule_approve(t uuid,ident uuid,m date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE q finance_entry_drafts;j uuid;l jsonb;n int:=0;i finance_deferred_items;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin approval required';END IF;SELECT * INTO q FROM finance_entry_drafts WHERE id=ident AND tenant_id=t AND status='waiting' AND date_trunc('month',entry_date)::date=date_trunc('month',m)::date FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Draft changed; refresh';END IF;PERFORM finance_assert_open(t,q.entry_date);
IF q.source_data ? 'item' THEN SELECT * INTO i FROM finance_deferred_items WHERE id=(q.source_data->>'item')::uuid AND tenant_id=t FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION 'Deferred item unavailable';END IF;IF q.source_data->>'action'='sold' THEN IF i.status<>'draft' THEN RAISE EXCEPTION 'Already recorded';END IF;ELSE IF i.status<>'active' OR i.used_amount IS DISTINCT FROM (q.source_data->>'expected_used')::numeric OR (q.source_data->>'amount')::numeric>i.amount-i.used_amount THEN RAISE EXCEPTION 'Deferred balance changed; prepare again';END IF;END IF;END IF;
IF q.kind='depreciation' AND NOT EXISTS(SELECT 1 FROM fixed_assets WHERE tenant_id=t AND id=(q.source_data->>'asset')::uuid AND status='active' AND amount_depreciated=(q.source_data->>'expected_depreciated')::numeric) THEN RAISE EXCEPTION 'Asset changed';END IF;
INSERT INTO journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,created_by) VALUES(t,q.entry_date,q.label,CASE WHEN q.kind='manual' THEN 'manual' WHEN q.kind='depreciation' THEN 'depreciation' ELSE 'adjustment' END,q.id::text,'draft',auth.uid()) RETURNING id INTO j;
FOR l IN SELECT * FROM jsonb_array_elements(q.lines) LOOP n:=n+1;IF NOT EXISTS(SELECT 1 FROM chart_of_accounts WHERE tenant_id=t AND id=(l->>'account_id')::uuid AND is_active) THEN RAISE EXCEPTION 'Account changed';END IF;INSERT INTO journal_lines(tenant_id,entry_id,account_id,debit,credit,memo,line_no,venue) VALUES(t,j,(l->>'account_id')::uuid,coalesce((l->>'debit')::numeric,0),coalesce((l->>'credit')::numeric,0),q.reason,n,l->>'venue');END LOOP;IF (SELECT sum(debit-credit) FROM journal_lines WHERE entry_id=j)<>0 THEN RAISE EXCEPTION 'Draft not balanced';END IF;
UPDATE journal_entries SET status='posted',posted_at=now() WHERE id=j AND tenant_id=t AND status='draft';UPDATE finance_entry_drafts SET status='approved',journal_entry_id=j,approved_by=auth.uid(),approved_at=now() WHERE id=q.id;
IF q.source_data ? 'item' THEN IF q.source_data->>'action'='sold' THEN UPDATE finance_deferred_items SET status='active' WHERE id=i.id;ELSE UPDATE finance_deferred_items SET used_amount=used_amount+(q.source_data->>'amount')::numeric,status=CASE WHEN used_amount+(q.source_data->>'amount')::numeric=amount THEN 'closed' ELSE 'active' END WHERE id=i.id;END IF;END IF;
IF q.kind='depreciation' THEN UPDATE fixed_assets SET amount_depreciated=amount_depreciated+(q.source_data->>'amount')::numeric,amount_remaining=greatest(0,cost-salvage_value-amount_depreciated-(q.source_data->>'amount')::numeric) WHERE id=(q.source_data->>'asset')::uuid AND tenant_id=t;UPDATE fixed_asset_depreciation_schedule SET status='posted',posted_amount=scheduled_amount,journal_entry_id=j,posted_at=now() WHERE tenant_id=t AND asset_id=(q.source_data->>'asset')::uuid AND period_year=extract(year FROM q.entry_date) AND period_month=extract(month FROM q.entry_date);END IF;
INSERT INTO audit_log(tenant_id,user_id,action,entity_type,entity_id,details) VALUES(t,auth.uid(),'finance_draft_approved','finance_entry_drafts',q.id::text,jsonb_build_object('kind',q.kind,'journal',j,'reason',q.reason,'document',q.source_document,'linked_entry',q.linked_entry_id));RETURN j;END $$;REVOKE ALL ON FUNCTION public.finance_schedule_approve(uuid,uuid,date) FROM PUBLIC;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.expense_month_approve(uuid,date,jsonb)'::regprocedure) INTO def;def:=replace(def,'ELSE RAISE EXCEPTION ''Unknown monthly draft'';','ELSIF item->>''kind''=''schedule'' THEN PERFORM public.finance_schedule_approve(t,ident,m); ELSE RAISE EXCEPTION ''Unknown monthly draft'';');EXECUTE def;END $$;
CREATE FUNCTION public.finance_schedule_prepare(t uuid,m date) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s finance_schedule_settings;a fixed_assets;i finance_deferred_items;ending date:=(date_trunc('month',m)+interval '1 month -1 day')::date;n int:=0;amt numeric;debit uuid;credit uuid;profit numeric;setaside numeric;fy date;lastvalue numeric;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;IF ending>(now() AT TIME ZONE 'Asia/Hong_Kong')::date THEN RAISE EXCEPTION 'Only completed months can be prepared';END IF;PERFORM finance_assert_open(t,ending);SELECT * INTO s FROM finance_schedule_settings WHERE tenant_id=t;
FOR a IN SELECT * FROM fixed_assets WHERE tenant_id=t AND status='active' AND in_service_date<=ending LOOP amt:=least(round((a.cost-a.salvage_value)/a.useful_life_months,2),a.cost-a.salvage_value-a.amount_depreciated);IF amt>0 AND a.expense_account_id IS NOT NULL AND a.accumulated_depr_account_id IS NOT NULL THEN PERFORM finance_schedule_enqueue(t,ending,'depreciation',a.name||' · depreciation','Straight-line monthly depreciation','depreciation:'||a.id||':'||date_trunc('month',m)::date,jsonb_build_array(jsonb_build_object('account_id',a.expense_account_id,'debit',amt,'credit',0,'venue',a.venue),jsonb_build_object('account_id',a.accumulated_depr_account_id,'debit',0,'credit',amt,'venue',a.venue)),jsonb_build_object('asset',a.id,'amount',amt,'expected_depreciated',a.amount_depreciated));n:=n+1;END IF;END LOOP;
FOR i IN SELECT * FROM finance_deferred_items WHERE tenant_id=t AND status='active' AND issued_date<=ending LOOP amt:=0;credit:=NULL;IF i.kind='voucher' AND i.expires_on<=ending THEN amt:=i.amount-i.used_amount;credit:=finance_schedule_account(t,'4900','Unused voucher income','other_income');ELSIF i.kind='package' AND date_trunc('month',m)::date<date_trunc('month',i.issued_date)::date+make_interval(months=>i.release_months) THEN amt:=least(round(i.amount/i.release_months,2),i.amount-i.used_amount);SELECT id INTO credit FROM chart_of_accounts WHERE tenant_id=t AND account_type='revenue' AND code='4000';END IF;IF amt>0 AND credit IS NOT NULL THEN SELECT id INTO debit FROM chart_of_accounts WHERE tenant_id=t AND code='2300';PERFORM finance_schedule_enqueue(t,ending,CASE WHEN i.kind='voucher' THEN 'deferred_expiry' ELSE 'package_release' END,i.reference||' · deferred release','Monthly deferred revenue release','deferred-release:'||i.id||':'||date_trunc('month',m)::date,jsonb_build_array(jsonb_build_object('account_id',debit,'debit',amt,'credit',0,'venue',i.venue),jsonb_build_object('account_id',credit,'debit',0,'credit',amt,'venue',i.venue)),jsonb_build_object('item',i.id,'action','release','amount',amt,'expected_used',i.used_amount));n:=n+1;END IF;END LOOP;
IF s.tax_enabled THEN fy:=make_date(extract(year FROM ending)::int,s.year_end_month,least(s.year_end_day,extract(day FROM (make_date(extract(year FROM ending)::int,s.year_end_month,1)+interval '1 month -1 day'))::int))+1;IF fy>ending THEN fy:=(fy-interval '1 year')::date;END IF;
SELECT coalesce(sum(l.credit-l.debit),0) INTO profit FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN chart_of_accounts c ON c.id=l.account_id WHERE e.tenant_id=t AND e.status='posted' AND e.entry_date BETWEEN fy AND ending AND c.account_type IN('revenue','other_income','cogs','opex','other_expense') AND c.code<>'6950';profit:=greatest(profit,0);setaside:=round(least(profit,2000000)*CASE WHEN s.business_type='company' THEN 0.0825 ELSE 0.075 END+greatest(profit-2000000,0)*CASE WHEN s.business_type='company' THEN 0.165 ELSE 0.15 END,2);SELECT coalesce(sum(l.debit-l.credit),0) INTO lastvalue FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id JOIN chart_of_accounts c ON c.id=l.account_id WHERE e.tenant_id=t AND e.status='posted' AND e.entry_date BETWEEN fy AND ending AND c.code='6950';amt:=setaside-lastvalue;IF amt<>0 THEN SELECT id INTO debit FROM chart_of_accounts WHERE tenant_id=t AND code='6950';SELECT id INTO credit FROM chart_of_accounts WHERE tenant_id=t AND code='2350';PERFORM finance_schedule_enqueue(t,ending,'tax','Profits tax · monthly set-aside','HK two-tier estimate on book profit; accountant review required','tax:'||date_trunc('month',m)::date,jsonb_build_array(jsonb_build_object('account_id',debit,'debit',greatest(amt,0),'credit',greatest(-amt,0)),jsonb_build_object('account_id',credit,'debit',greatest(-amt,0),'credit',greatest(amt,0))),jsonb_build_object('profit',profit,'target_tax',setaside));n:=n+1;END IF;END IF;
PERFORM expense_monthend_run(t,m);RETURN n;END $$;REVOKE ALL ON FUNCTION public.finance_schedule_prepare(uuid,date) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.finance_schedule_prepare(uuid,date) TO authenticated;